const Card = ({ children, style, onClick, className }) => (
  <div onClick={onClick} className={(onClick ? "tap " : "") + (className || "")} style={{ background: C.card, borderRadius: 20, padding: 16, boxShadow: "0 1px 2px rgba(0,0,0,.04), 0 0 0 1px rgba(0,0,0,.03)", ...style }}>{children}</div>
);
