const LiveBadge = ({ time, mono, countdown }) => (
  <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, lineHeight: 1.2 }}>
    {/* wrapper is sized to the halo's own max radius (dot scales to 2.6x via kdotping), not the
        bare 6px dot -- otherwise the gap below measures from the dot's edge and the halo visibly
        overlaps the text */}
    <span style={{ position: "relative", width: 16, height: 16, flexShrink: 0 }}>
      <span className="kdot-ping" style={{ position: "absolute", top: 5, left: 5, width: 6, height: 6, borderRadius: 3, background: C.down }} />
      <span style={{ position: "absolute", top: 5, left: 5, width: 6, height: 6, borderRadius: 3, background: C.down }} />
    </span>
    <span style={{ color: C.down, fontWeight: 700 }}><T>Live</T></span>
    {/* a countdown ("22:30:28" ticking down) is red like the Live badge itself; a plain
        start-time stamp ("4:00 PM") stays black and regular-weight */}
    {time && <span style={{ color: countdown ? C.down : C.ink, fontWeight: 400, fontFamily: mono ? MONO : undefined }}>{time}</span>}
  </div>
);
// deterministic stand-in avatars for traders whose profile image the API doesn't provide --
// same person always gets the same one, so the list doesn't reshuffle between renders
const AVATAR_BGS = ["#F6DF51", "#8FD5A6", "#9BB8F0", "#F0A6A6", "#C3A6F0", "#F0C58F"];
