/* swipe to confirm */
function Swipe({ label, color, onConfirm, disabled }) {
  const ref = useRef(); const [x, setX] = useState(0); const [drag, setDrag] = useState(false); const max = () => (ref.current?.offsetWidth || 300) - 56;
  const move = e => { if (!drag || disabled) return; const r = ref.current.getBoundingClientRect(); setX(Math.max(0, Math.min(max(), e.clientX - r.left - 28))); };
  const up = () => { if (!drag) return; setDrag(false); if (x > max() * .85) { setX(max()); onConfirm(); setTimeout(() => setX(0), 600); } else setX(0); };
  return (
    <div ref={ref} onPointerMove={move} onPointerUp={up} onPointerLeave={up} style={{ position: "relative", height: 56, borderRadius: 28, background: disabled ? C.soft : color + "22", border: `1.5px solid ${disabled ? C.line : color}`, overflow: "hidden", touchAction: "none", userSelect: "none" }}>
      <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", fontWeight: 600, fontSize: 15, color: C.ink, clipPath: `inset(0 0 0 ${x + 52}px)`, transition: drag ? "none" : "clip-path .25s" }}>{label}</div>
      <div onPointerDown={() => !disabled && setDrag(true)} style={{ position: "absolute", top: 2, left: 2 + x, width: 50, height: 50, borderRadius: 25, background: disabled ? C.mute : color, display: "grid", placeItems: "center", color: "#fff", transition: drag ? "none" : "left .25s", cursor: disabled ? "default" : "grab", boxShadow: "0 4px 12px rgba(0,0,0,.2)" }}><ArrowRight size={22} /></div>
    </div>
  );
}

