function MarketCard({ m, onOpen, compact }) {
  const { lang } = useLang();
  return (
    <Card onClick={() => onOpen(m)} style={{ padding: compact ? 14 : 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <div style={{ width: 30, height: 30, borderRadius: 9, background: C.soft, display: "grid", placeItems: "center", fontSize: 14 }}>{m.emoji}</div>
        <div style={{ flex: 1, minWidth: 0 }}><div style={{ fontSize: 12, color: C.mute, fontWeight: 600 }}>{m.league}{m.dur ? ` · ${translateDur(lang, m.dur)}` : ""}{m.fmt ? ` · ${m.fmt}` : ""}</div></div>
        <span style={{ fontSize: 12, color: m.live ? C.down : C.mute, fontWeight: 700, display: "flex", alignItems: "center", gap: 4 }}>{m.live && <span style={{ width: 6, height: 6, borderRadius: 3, background: C.down, animation: "blink 1.2s infinite" }} />}{m.live && m.score ? m.score : m.t}</span>
      </div>
      <div style={{ fontSize: compact ? 15 : 17, fontWeight: 800, letterSpacing: -0.3, marginBottom: 12, lineHeight: 1.3 }}>{m.title}</div>
      <div style={{ display: "grid", gap: 8 }}>{m.opts.map(o => (
        <div key={o.n} style={{ display: "flex", alignItems: "center", gap: 10 }}><Team n={o.n} size={26} /><span style={{ flex: 1, fontWeight: 700, fontSize: 15 }}><T>{o.n}</T></span><Pct n={o.n} p={o.p} /></div>))}</div>
      <div style={{ display: "flex", gap: 6, marginTop: 12 }}><span style={{ fontSize: 11, color: C.mute, background: C.soft, padding: "4px 9px", borderRadius: 999, display: "flex", alignItems: "center", gap: 4 }}><CircleDollarSign size={12} />{fmt(m.vol)}</span><span style={{ fontSize: 11, color: C.mute, background: C.soft, padding: "4px 9px", borderRadius: 999 }}>{m.cat}</span></div>
    </Card>
  );
}

