  const slideW = w ? w - SIDE * 2 : 0;   // centre slide = content width (edge of cards to edge of cards)
  const stepW = slideW + GAP;
  const baseX = SIDE - idx * stepW;      // centre the active slide within the full-width container
  const trackX = baseX + dx;
  const activeFloat = w ? (SIDE - trackX) / stepW : idx;
