function parsePx(px) {
  const hasDollar = px.trim().startsWith("$");
  const clean = px.replace(/[$,]/g, "");
  const num = parseFloat(clean) || 0;
  const dot = clean.indexOf(".");
  const decimals = dot === -1 ? 0 : clean.length - dot - 1;
  return { num, decimals, hasDollar };
}
function fmtPx(num, decimals, hasDollar) {
  const s = num.toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
  return (hasDollar ? "$" : "") + s;
}
function fmtChg(cur, base, decimals, hasDollar) {
  const diff = cur - base;
  const pct = base ? Math.abs(diff / base * 100) : 0;
  const sign = diff >= 0 ? "+" : "-";
  const absStr = Math.abs(diff).toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
  return `${sign}${hasDollar ? "$" : ""}${absStr} (${pct.toFixed(2)}%)`;
}
