// demo/offline contracts generator: gives multi-event markets in the artifact preview so the
// full market page (PredMarket) can be opened without hitting the Polymarket API — real numbers
// replace these once the H5 build fetches live data.
function genDemoContracts(seed, basePrice, n) {
  let s = seed || 1;
  const rnd = () => (s = (s * 16807) % 2147483647) / 2147483647;
  const step = basePrice >= 10000 ? 2000 : basePrice >= 1000 ? 100 : 1;
  const half = Math.floor(n / 2);
  const prices = Array.from({ length: n }, (_, i) => Math.round(basePrice + (i - half) * step));
  let pcts = []; let p0 = 34 + Math.floor(rnd() * 30);
  for (let i = 0; i < n; i++) { pcts.push(i === 0 ? p0 : Math.max(1, Math.round(pcts[i - 1] * (0.35 + rnd() * 0.45)))); }
  pcts.sort((a, b) => b - a);
  return prices.map((price, i) => ({ price, pct: pcts[i] })).sort((a, b) => b.pct - a.pct)
    .map((c, i) => ({ id: "d" + seed + "-c" + i, label: c.price.toLocaleString(), pct: c.pct, vol: fmtVol(400000 + rnd() * 4000000) }));
}
const BTC_FEED = (() => { const out = []; for (let i = 0; i < 10; i++) { const up = 79000 + i * 500; const dn = 78000 + i * 500; const p1 = 71 - i; const p2 = 70 - i; out.push({ id: "btc" + i, icon: null, emoji: "₿", iconBg: "#F7931A", q: "What price will Bitcoin hit on September 8?", token: "Bitcoin", catSub: "Crypto", desc: "This market resolves based on the official Binance BTCUSDT price during the specified window. Refer to the resolution source for exact timing and edge cases.", vol: `$${(36.5 - i).toFixed(1)}k`, rows: [{ dir: "up", px: up.toLocaleString(), pct: p1 }, { dir: "down", px: dn.toLocaleString(), pct: p2 }], contracts: genDemoContracts(1000 + i, 78000 + i * 500, 8 + (i % 6)) }); } return out; })();
