function LeveragePill({ value, max, onChange }) {
  const ref = useRef(null);
  const KNOB = 16; const HIT = 48;
  const trackW = () => { const w = ref.current?.offsetWidth || 200; return w - KNOB; };
  const frac = max > 1 ? (value - 1) / (max - 1) : 0;
  const setFromX = clientX => {
    if (!ref.current) return;
    const r = ref.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(trackW(), clientX - r.left - KNOB / 2));
    const f = trackW() > 0 ? x / trackW() : 0;
    onChange(1 + Math.round(f * (max - 1)));
  };
  const digits = String(max).length;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#F7F7F7", borderRadius: 999, padding: "3px 10px 3px 6px", flex: "0 1 210px", minWidth: 0 }}>
      <div ref={ref} style={{ position: "relative", flex: 1, minWidth: 60, height: KNOB, display: "flex", alignItems: "center", touchAction: "none", userSelect: "none" }}>
        <div style={{ position: "absolute", top: "50%", left: KNOB / 2, right: KNOB / 2, height: 3, transform: "translateY(-50%)", background: "#D8D6D0", borderRadius: 2 }} />
        <div style={{ position: "absolute", top: "50%", left: KNOB / 2, width: `calc(${frac} * (100% - ${KNOB}px))`, height: 3, transform: "translateY(-50%)", background: C.ink, borderRadius: 2 }} />
        <div style={{ position: "absolute", top: "50%", left: `calc(${frac} * (100% - ${KNOB}px))`, width: KNOB, height: KNOB, transform: "translateY(-50%)", borderRadius: "50%", background: C.ink, boxShadow: "0 2px 6px rgba(0,0,0,.25)", pointerEvents: "none" }} />
        <div onPointerDown={e => { e.currentTarget.setPointerCapture?.(e.pointerId); setFromX(e.clientX); }} onPointerMove={e => { if (e.currentTarget.hasPointerCapture?.(e.pointerId)) setFromX(e.clientX); }} style={{ position: "absolute", left: -8, right: -8, top: (KNOB - HIT) / 2, height: HIT, cursor: "pointer", touchAction: "none" }} />
      </div>
      <span style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 13, fontWeight: 550, color: C.ink, whiteSpace: "nowrap", lineHeight: 1, flexShrink: 0 }}><b style={{ fontFamily: MONO, minWidth: `${digits + 1}ch`, textAlign: "right" }}>{value}x</b><T>leverage</T></span>
    </div>
  );
}
