function Waterfall({ notional, chain }) {
  const { lang } = useLang(); const t = s => translate(lang, s);
  const top = chain[0].rate;
  const rows = useMemo(() => chain.map((a, i) => { const next = chain[i + 1]?.rate ?? 0; return { name: a.name, rate: a.rate, cut: a.rate - next, color: i === 0 ? C.amber : C.brand }; }), [chain]);
  return <div>
    <div style={{ display: "flex", height: 16, borderRadius: 8, overflow: "hidden", background: C.soft, marginBottom: 12, gap: 2 }}>{rows.map((r, i) => <div key={i} style={{ width: `${(r.cut / top) * 100}%`, background: r.color, transition: "width .3s cubic-bezier(.2,.8,.2,1)" }} />)}</div>
    {rows.map((r, i) => <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 0", borderBottom: i < rows.length - 1 ? `1px dashed ${C.line}` : "none" }}><span style={{ width: 12, height: 12, borderRadius: "50%", background: r.color, flexShrink: 0 }} /><span style={{ flex: 1, fontSize: 14, fontWeight: 700 }}>{r.name}{r.rate != null && <span style={{ color: C.mute, fontWeight: 500, fontFamily: MONO, fontSize: 12 }}> {r.rate.toFixed(2)}%</span>}</span><span style={{ fontSize: 11, color: C.mute, fontFamily: MONO }}>{t("spread")} {r.cut.toFixed(2)}%</span><N s={15}>{money(notional * r.cut / 100)}</N></div>)}
    <div style={{ display: "flex", justifyContent: "space-between", marginTop: 12, fontSize: 12, color: C.mute, background: "#F2F2F2", padding: "8px 12px", borderRadius: 10 }}><span>{money(notional)} {t("traded × your rate")} {top.toFixed(2)}%</span><b style={{ color: C.ink, fontFamily: MONO }}>= {money(notional * top / 100)}</b></div>
  </div>;
}
