function translate(lang, s) {
  if (!s || lang === "English") return s;
  const d = I18N[lang];
  return (d && d[s] != null) ? d[s] : s; // fallback to English source
}
const MONTH_MAP = { Jan: 1, Feb: 2, Mar: 3, Apr: 4, May: 5, Jun: 6, Jul: 7, Aug: 8, Sep: 9, Oct: 10, Nov: 11, Dec: 12 };
function fmtDate(lang, s) {
  if (lang !== "简体中文" || !s) return s;
  const m = /^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$/.exec(s);
  if (!m) return s;
  const [, d, mon, y] = m;
  const mm = MONTH_MAP[mon];
  return mm ? `${y}年${mm}月${d}日` : s;
}
function fmtDateTime(lang, s) {
  if (lang !== "简体中文" || !s) return s;
  const m = /^(\d{4})\.(\d{1,2})\.(\d{1,2})\s+(\d{1,2}:\d{2})$/.exec(s);
  if (!m) return s;
  const [, y, mo, d, hm] = m;
  return `${y}年${+mo}月${+d}日 ${hm}`;
}
function translateDur(lang, s) {
  if (lang !== "简体中文" || !s) return s;
  return s.replace(/(\d+)\s*min\b/g, "$1分钟");
}
function translateFrom(lang, s) {
  if (lang !== "简体中文" || !s) return s;
  const m = /^(.+)'s team$/.exec(s);
  if (m) return `${m[1]} 团队`;
  return s;
}
function T({ children }) {
  const { lang } = useLang();
  if (typeof children !== "string") return children;
  return translate(lang, children);
}

